    const manager = managerFor(project); const currentRecords = this.research.submitted(project.projectId); for (const result of roundResults) { const proposal = proposals.find((entry) => entry.experimentId === result.experimentId)!; const frozen = manager.assertFrozen(result.experimentId, result.evaluatedCommit, execution.value.evaluationContractHash); const sequence = [...currentRecords].reverse().find((entry) => entry.event.scope.autoresearchId === execution.entityId && (entry.record as { $schema?: string; experimentId?: string }).$schema === schemaUri("experiment-result") && (entry.record as { experimentId?: string }).experimentId === result.experimentId)?.event.sequence ?? 0; const accepted = promoted.includes(result.experimentId); const manifest: JsonValue = { $schema: schemaUri("experiment-manifest"), schemaVersion: 1, experimentId: result.experimentId, autoresearchId: execution.entityId, proposalId: proposal.proposalId, parentExperimentId: result.parentExperimentId, treeDepth: round, round, hypothesis: proposal.hypothesis, primaryChange: proposal.primaryChange, ideaFingerprint: proposal.novelty.ideaFingerprint, attemptFingerprint: result.attemptFingerprint, branch: result.branch, worktreeId: `wt_${result.experimentId.slice(4)}`, parentCommit: frozen.parentCommit, implementationCommit: frozen.evaluatedCommit, evaluatedCommit: frozen.evaluatedCommit, evaluationContractHash: execution.value.evaluationContractHash, state: accepted ? "accepted" : "rejected", runIds: result.runIds, resultRecordSequence: sequence, reviewId: accepted ? request.reviewId : result.reviewId, promotionDecision: accepted ? "promoted" : "rejected", artifactIds: result.artifactIds, createdAt: proposal.submittedAt, evaluatedAt: result.completedAt }; this.submit(project, execution.value, `experiment:${result.experimentId}`, manifest, `experiment-manifest:${result.experimentId}`, null, result.experimentId); }
    const roundRecord: JsonValue = { $schema: schemaUri("autoresearch-round"), schemaVersion: 1, autoresearchId: execution.entityId, round, inputFrontierExperimentIds: round === 1 ? [execution.value.rootExperimentId] : execution.value.acceptedFrontierExperimentIds, proposedExperimentIds: proposals.map((proposal) => proposal.experimentId), evaluatedExperimentIds: roundResults.map((result) => result.experimentId), promotedExperimentIds: promoted, rejectedExperimentIds: roundResults.filter((result) => !promoted.includes(result.experimentId)).map((result) => result.experimentId), progressDelta: { reviewedExperiments: roundResults.length, promoted: promoted.length }, focusCheck: { distinctIdeaFamiliesInWindow: new Set(proposals.map((proposal) => proposal.novelty.ideaFingerprint)).size, repeatedFingerprintCount: proposals.length - new Set(proposals.map((proposal) => proposal.novelty.ideaFingerprint)).size, noProgressCount: promoted.length ? 0 : 1, action: promoted.length ? "continue" : "stop" }, reviewId: request.reviewId, nextRoundPurpose: promoted.length ? "Descend from the reviewed winner" : "Stop because no candidate passed", completedAt: new Date().toISOString() }; this.submit(project, execution.value, `autoresearch:${execution.entityId}`, roundRecord, `autoresearch-round:${execution.entityId}:${round}`, reviewerId); this.research.advanceAutoresearch(project.projectId, execution.entityId, execution.version, round, promoted.length ? promoted : execution.value.acceptedFrontierExperimentIds, `autoresearch-round-projection:${execution.entityId}:${round}`);
