  private write(projectId: string, key: string, path: string, value: JsonValue): string { const content = `${canonicalJson(value)}\n`; const digest = sha256(content); const intent = this.research.beginExternalOperation(projectId, "filesystem.write", `filesystem-write:${key}`, { path: resolve(path), digest, content }); mkdirSync(resolve(path, ".."), { recursive: true }); if (!existsSync(path) || sha256(readFileSync(path, "utf8")) !== digest) { const temporary = `${path}.${intent.intentId}.tmp`; writeFileSync(temporary, content, "utf8"); renameSync(temporary, path); } if (sha256(readFileSync(path, "utf8")) !== digest) throw new Error("Durable file write verification failed"); this.research.completeExternalOperation(projectId, intent.intentId, { path: resolve(path), digest }); return path; }
