type TaskPacket = { $schema: string; schemaVersion: number; templateVersion: string; taskId: string; attempt: number; taskType: string; assignedRole: "general_worker"; assignedAgentId: string; scope: { projectId: string; missionId: string | null; directionId: string | null; autoresearchId: string; experimentId: string; graphNodeId: string }; goalStack: { projectGoalId: string; projectGoalSummary: string; missionCriterionIds: string[]; missionCriterionSummary: string; directionQuestionId: string | null; directionQuestionSummary: string | null; nodeObjective: string }; whyNow: string; instructions: string[]; inScope: string[]; outOfScope: string[]; inputArtifactIds: string[]; inputEvidenceIds: string[]; requiredOutputs: Array<{ outputId: string; kind: string; required: boolean }>; acceptanceCriteria: Array<{ criterionId: string; statement: string; validatorIds: string[]; reviewRubricIds: string[]; required: boolean }>; workspace: { worktreeId: string; branch: string; startingCommit: string; writeScopes: string[]; protectedScopes: string[] }; permissions: { network: string; subprocess: string; gitCommit: boolean; gitPush: boolean; delegation: "request_only"; allowedToolIds: string[] }; budget: { deadline: string; maximumWallClockSeconds: number; maximumModelTokens: number; maximumToolCalls: number; maximumRepairAttempts: number }; progressPolicy: { milestoneIntervalSeconds: number; emitOnFirstDurableDelta: boolean; emitOnBlocker: boolean; emitOnAnomaly: boolean; maximumSilentSeconds: number }; responseSchema: string; observedVersions: Record<string, number>; lease: { leaseId: string; expiresAt: string; heartbeatSeconds: number }; issuedBy: "research_director"; issuedAt: string };
